<script setup lang="ts">
const route=useRoute()
const {data:services,error:serviceError}=await useFetch<any[]>('/api/public/services')
const {data:holidays}=await useFetch<string[]>('/api/public/holidays')
const {data:siteData}=useClinic()
const current=ref(1)
const serviceId=ref<number|null>(null)
const date=ref(''),time=ref(''),slots=ref<string[]>([])
const availabilityLoading=ref(false),availabilityError=ref('')
const patientName=ref(''),mobile=ref(''),notes=ref('')
const submitting=ref(false),error=ref(''),confirmation=ref<any>(null)
const selectedService=computed(()=>services.value?.find(s=>Number(s.id)===Number(serviceId.value)))
const steps=['انتخاب خدمت','تاریخ و ساعت','اطلاعات شما','تأیید نهایی']
const dateLabel=computed(()=>date.value?faDate(date.value,siteData.value?.site?.timezone):'')
let loadId=0
watch([serviceId,date],async()=>{
  const id=++loadId
  time.value='';slots.value=[];availabilityError.value=''
  if(!serviceId.value||!date.value)return
  availabilityLoading.value=true
  try {const result=await $fetch<{slots:string[]}>('/api/public/availability',{query:{serviceId:serviceId.value,date:date.value}});if(id===loadId)slots.value=result.slots}
  catch(e){if(id===loadId)availabilityError.value=humanError(e)}
  finally{if(id===loadId)availabilityLoading.value=false}
})
onMounted(()=>{
  const q=Number(route.query.service)
  if(q && services.value?.some(s=>Number(s.id)===q))serviceId.value=q
})
function next(){error.value='';if(current.value===1&&!serviceId.value){error.value='ابتدا نوع خدمت را انتخاب کنید.';return}if(current.value===2&&(!date.value||!time.value)){error.value='تاریخ و ساعت آزاد را انتخاب کنید.';return}if(current.value===3){if(patientName.value.trim().length<3){error.value='نام و نام خانوادگی را وارد کنید.';return}if(!/^09\d{9}$/.test(normalizedMobile.value)){error.value='شماره موبایل معتبر وارد کنید.';return}}current.value++}
const normalizedMobile=computed(()=>mobile.value.replace(/[۰-۹]/g,c=>String('۰۱۲۳۴۵۶۷۸۹'.indexOf(c))).replace(/[٠-٩]/g,c=>String('٠١٢٣٤٥٦٧٨٩'.indexOf(c))).replace(/[\s-]/g,'').replace(/^\+98/,'0'))
async function submit(){error.value='';submitting.value=true;try{confirmation.value=await $fetch('/api/public/bookings',{method:'POST',body:{serviceId:serviceId.value,date:date.value,time:time.value,patientName:patientName.value,mobile:normalizedMobile.value,notes:notes.value}});current.value=5;window.scrollTo({top:0,behavior:'smooth'})}catch(e){error.value=humanError(e);if((e as any)?.statusCode===409){current.value=2}}finally{submitting.value=false}}
useSeoMeta({title:'رزرو نوبت آنلاین | دکتر آزاده مهرداد',description:'دریافت نوبت دندانپزشکی با انتخاب خدمت، تقویم شمسی و ساعت‌های آزاد بدون نیاز به ثبت نام.'})
</script>
<template>
  <div class="bg-[#f7faf7] min-h-screen pb-24 md:pb-20">
    <div class="bg-[#eff7f0] pt-12 pb-20"><div class="container-wrap"><span class="eyebrow">نوبت‌دهی آسان و آنلاین</span><h1 class="section-title mt-2">رزرو <span class="text-[#2f9079]">نوبت دندانپزشکی</span></h1><p class="body-muted mt-1">در چند مرحله ساده، زمان مراجعه خود را انتخاب کنید.</p></div></div>
    <div class="container-wrap -mt-10 relative z-10 max-w-[960px]">
      <div v-if="current<5" class="glass-card px-5 py-5 sm:px-8 sm:py-6 mb-5"><div class="flex items-center justify-between gap-1"><div v-for="(step,i) in steps" :key="step" class="flex items-center gap-2" :class="i+1<=current?'text-jade-700':'text-[#aabbb2]'"><span class="w-8 h-8 sm:w-10 sm:h-10 rounded-full grid place-items-center text-xs font-bold" :class="i+1<current?'bg-jade-700 text-white':i+1===current?'bg-[#e3f1e8] text-jade-800 ring-1 ring-[#aed2ba]':'bg-[#f1f5f1]'"><Icon v-if="i+1<current" name="check" :size="17" /><span v-else>{{faNumber(i+1)}}</span></span><span class="hidden md:block text-xs font-bold">{{step}}</span></div></div><div class="h-1.5 rounded-full bg-[#edf3ee] mt-5 overflow-hidden"><div class="bg-[#348e78] h-full rounded-full transition-all duration-500" :style="{width:`${(current/4)*100}%`}"></div></div></div>
      <div v-if="current===5 && confirmation" class="glass-card py-14 px-8 text-center anim-up"><span class="w-20 h-20 bg-[#e6f6eb] rounded-full mx-auto grid place-items-center text-[#2e9276] mb-6"><Icon name="check-circle-2" :size="45" /></span><h2 class="text-[25px] font-extrabold text-jade-800">نوبت شما با موفقیت ثبت شد!</h2><p class="body-muted mt-2">کد پیگیری را ذخیره کنید؛ برای مشاهده، لغو یا تغییر نوبت به آن نیاز دارید.</p><div class="bg-[#f0f8f2] border border-[#dcece0] rounded-2xl max-w-sm mx-auto p-6 mt-8"><span class="text-xs text-[#779688]">کد پیگیری اختصاصی</span><p class="text-3xl tracking-[.14em] font-black mt-2 text-jade-800" dir="ltr">{{confirmation.code}}</p><div class="divider my-5"></div><p class="text-xs leading-8">{{confirmation.service}}</p><p class="text-xs leading-8">{{dateLabel}}، ساعت {{confirmation.time}}</p></div><p class="text-xs text-[#859a8d] mt-6">{{confirmation.smsSent?'پیامک تأیید ارسال شد.':'کد پیگیری را یادداشت کنید؛ ارسال پیامک در حال حاضر فعال یا تأیید نشده است.'}}</p><div class="flex flex-wrap justify-center gap-3 mt-8"><NuxtLink to="/track" class="btn-main">پیگیری نوبت <Icon name="arrow-left" :size="17" /></NuxtLink><NuxtLink to="/" class="btn-light">بازگشت به صفحه اصلی</NuxtLink></div></div>
      <div v-else class="glass-card p-6 sm:p-10">
        <div v-if="current===1"><div class="flex gap-3 items-center mb-8"><span class="bg-jade-50 text-jade-700 p-3 rounded-xl"><Icon name="clipboard-list" /></span><div><h2 class="font-extrabold text-lg text-jade-800">چه خدمتی نیاز دارید؟</h2><p class="text-xs text-[#91a498] mt-1">برای مشاهده ساعت‌های مناسب، نوع خدمت را انتخاب کنید.</p></div></div><div v-if="services?.length" class="grid sm:grid-cols-2 gap-3"><button v-for="s in services" :key="s.id" type="button" class="text-right flex gap-3 p-4 rounded-2xl border transition-colors" :class="serviceId===Number(s.id)?'border-[#469985] bg-[#eff8f1]':'border-[#e4eee6] hover:bg-[#fafdfa]'" @click="serviceId=Number(s.id)"><span class="w-11 h-11 rounded-xl bg-white text-[#257866] grid place-items-center shrink-0"><Icon :name="s.icon" :size="23" /></span><span class="flex-1"><strong class="text-[13px] text-jade-800 block">{{s.name}}</strong><small class="text-[11px] text-[#95a79d] mt-1 block">زمان تقریبی {{faNumber(s.duration_minutes)}} دقیقه</small></span><Icon :name="serviceId===Number(s.id)?'check-circle-2':'circle'" :size="19" class="text-[#298a74] self-center" /></button></div><p v-else class="text-xs text-rose-600">{{serviceError?'امکان دریافت خدمات از سرور وجود ندارد.':'خدمت فعالی تعریف نشده است.'}}</p></div>
        <div v-if="current===2"><div class="flex gap-3 items-center mb-8"><span class="bg-jade-50 text-jade-700 p-3 rounded-xl"><Icon name="calendar-days" /></span><div><h2 class="font-extrabold text-lg text-jade-800">روز و ساعت مراجعه</h2><p class="text-xs text-[#91a498] mt-1">روز دلخواهتان را از تقویم شمسی انتخاب کنید.</p></div></div><div class="grid lg:grid-cols-2 gap-7"><div><p class="field-label">تاریخ مراجعه</p><JalaliCalendar v-model="date" :timezone="siteData?.site?.timezone" :horizon="siteData?.site?.booking_horizon_days" :blocked-dates="holidays||[]" :working-hours="siteData?.site?.working_hours" /></div><div><p class="field-label">ساعت‌های آزاد {{date?'در '+dateLabel:''}}</p><div class="bg-[#f8fbf8] border border-[#e6eee8] rounded-2xl p-5 min-h-[300px]"><div v-if="!date" class="h-[260px] flex flex-col items-center justify-center gap-4 text-[#a7bbae]"><Icon name="calendar-clock" :size="42" :stroke-width="1.2" /><span class="text-xs">ابتدا یک روز از تقویم انتخاب کنید</span></div><div v-else-if="availabilityLoading" class="h-[260px] grid place-items-center text-xs text-jade-700"><span class="flex items-center gap-3"><Icon name="loader-circle" class="animate-spin" /> در حال بررسی ساعت‌های آزاد...</span></div><p v-else-if="availabilityError" class="text-xs text-rose-600 leading-8">{{availabilityError}}</p><div v-else-if="slots.length" class="grid grid-cols-3 gap-2.5"><button v-for="slot in slots" :key="slot" type="button" class="rounded-xl border py-3 text-xs font-bold" :class="time===slot?'bg-jade-700 text-white border-jade-700':'bg-white text-jade-700 border-[#dfece3] hover:border-[#66b19d]'" @click="time=slot" dir="ltr">{{slot}}</button></div><div v-else class="h-[260px] grid place-items-center"><div class="text-center"><Icon name="calendar-off" :size="35" class="mx-auto text-[#94afa1] mb-3" /><p class="text-xs leading-8 text-[#779083]">برای این روز ساعت آزادی وجود ندارد.<br />روز دیگری انتخاب کنید.</p></div></div></div></div></div></div>
        <div v-if="current===3"><div class="flex gap-3 items-center mb-8"><span class="bg-jade-50 text-jade-700 p-3 rounded-xl"><Icon name="user-round" /></span><div><h2 class="font-extrabold text-lg text-jade-800">اطلاعات مراجعه‌کننده</h2><p class="text-xs text-[#91a498] mt-1">برای تکمیل رزرو، مشخصات تماس را وارد کنید.</p></div></div><div class="grid sm:grid-cols-2 gap-5"><div class="sm:col-span-2"><label class="field-label" for="full-name">نام و نام خانوادگی *</label><input id="full-name" v-model="patientName" class="input-field" autocomplete="name" maxlength="120" placeholder="مثلاً: مریم احمدی" /></div><div class="sm:col-span-2"><label class="field-label" for="mobile">شماره موبایل *</label><input id="mobile" v-model="mobile" class="input-field" dir="ltr" inputmode="tel" autocomplete="tel" maxlength="20" placeholder="09123456789" /><p class="text-[11px] text-[#9aaa9f] mt-2">برای پیگیری، لغو یا تغییر نوبت به همین شماره نیاز دارید.</p></div><div class="sm:col-span-2"><label class="field-label" for="notes">توضیحات (اختیاری)</label><textarea id="notes" v-model="notes" rows="3" maxlength="1000" class="input-field" placeholder="توضیح مختصر درباره درخواست شما، بدون ثبت اطلاعات حساس پزشکی"></textarea></div></div><p class="flex gap-2 items-center text-xs text-[#718b7e] bg-[#eef7ef] p-4 rounded-xl mt-6"><Icon name="shield-check" :size="19" class="shrink-0" /> اطلاعات شما فقط برای مدیریت درخواست نوبت استفاده می‌شود.</p></div>
        <div v-if="current===4"><div class="flex gap-3 items-center mb-8"><span class="bg-jade-50 text-jade-700 p-3 rounded-xl"><Icon name="clipboard-check" /></span><div><h2 class="font-extrabold text-lg text-jade-800">بررسی و تأیید نهایی</h2><p class="text-xs text-[#91a498] mt-1">پیش از ثبت نهایی، اطلاعات خود را بررسی کنید.</p></div></div><dl class="bg-[#f6faf7] rounded-2xl border border-[#e8efe8] p-6 space-y-5"><div class="flex justify-between gap-4 text-[13px]"><dt class="text-[#829b8c]">خدمت انتخابی</dt><dd class="font-bold text-jade-800">{{selectedService?.name}}</dd></div><div class="divider"></div><div class="flex justify-between gap-4 text-[13px]"><dt class="text-[#829b8c]">تاریخ مراجعه</dt><dd class="font-bold text-jade-800">{{dateLabel}}</dd></div><div class="divider"></div><div class="flex justify-between gap-4 text-[13px]"><dt class="text-[#829b8c]">ساعت مراجعه</dt><dd class="font-bold text-jade-800" dir="ltr">{{time}}</dd></div><div class="divider"></div><div class="flex justify-between gap-4 text-[13px]"><dt class="text-[#829b8c]">نام مراجعه‌کننده</dt><dd class="font-bold text-jade-800">{{patientName}}</dd></div><div class="divider"></div><div class="flex justify-between gap-4 text-[13px]"><dt class="text-[#829b8c]">شماره موبایل</dt><dd class="font-bold text-jade-800" dir="ltr">{{normalizedMobile}}</dd></div></dl><p class="text-xs text-[#859d8e] mt-6 leading-7">با ثبت نهایی نوبت، زمان موردنظر برای شما رزرو می‌شود. قوانین لغو و تغییر نوبت در بخش پیگیری اعمال می‌شوند.</p></div>
        <div v-if="error" role="alert" class="mt-5 text-xs text-red-700 bg-red-50 border border-red-100 p-4 rounded-xl flex gap-2 items-start"><Icon name="alert-circle" :size="18" class="shrink-0" />{{error}}</div>
        <div class="border-t border-[#ecf2ed] pt-7 mt-8 flex gap-3 justify-between"><button type="button" class="btn-light" :class="current===1?'invisible':''" @click="current--,error=''">مرحله قبل</button><button v-if="current<4" type="button" class="btn-main" @click="next">ادامه <Icon name="arrow-left" :size="17" /></button><button v-else type="button" class="btn-main" :disabled="submitting" @click="submit"><Icon :name="submitting?'loader-circle':'check-circle-2'" :class="submitting?'animate-spin':''" :size="17" />{{submitting?'در حال ثبت...':'تأیید و ثبت نهایی'}}</button></div>
      </div>
      <p v-if="current<5" class="mt-5 text-center text-[#879c91] text-xs">قبلاً نوبت گرفته‌اید؟ <NuxtLink to="/track" class="text-jade-700 font-bold hover:underline">پیگیری یا تغییر نوبت</NuxtLink></p>
    </div>
  </div>
</template>
